CREATE OR REPLACE FUNCTION public.enforce_booking_four_hour_minimum()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_slot_time text;
  v_scheduled_at timestamptz;
begin
  if tg_op = 'INSERT' then
    if new.status = 'pending' then
      select pg_catalog.btrim(slot_time) into v_slot_time
        from public.availability_slots
       where id = new.slot_id;
      if v_slot_time is null or v_slot_time !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}'
         or v_slot_time like 'weekly:%' then
        raise exception 'A concrete booking slot is required.' using errcode = '23514';
      end if;
      begin
        if v_slot_time ~* '(Z|[+-][0-9]{2}(:[0-9]{2}|[0-9]{2})?)$' then
          v_scheduled_at := v_slot_time::timestamptz;
        else
          v_scheduled_at := v_slot_time::timestamp at time zone 'Asia/Seoul';
        end if;
      exception when others then
        raise exception 'Booking slot time is invalid.' using errcode = '22007';
      end;
    elsif new.status = 'confirmed' then
      v_scheduled_at := new.scheduled_at;
    else
      return new;
    end if;
  elsif tg_op = 'UPDATE' then
    if (old.status = 'pending' and new.status = 'confirmed')
       or (old.status = 'confirmed' and new.status = 'confirmed'
           and new.scheduled_at is distinct from old.scheduled_at) then
      v_scheduled_at := new.scheduled_at;
    else
      return new;
    end if;
  else
    return new;
  end if;

  if v_scheduled_at is null then
    raise exception 'A scheduled booking time is required.' using errcode = '23514';
  end if;

  -- Reuse 049's existing pre-open internal/admin/service test gate. This
  -- exempts only the lead time, not the concrete slot requirement above.
  if not public.dayo_can_bypass_booking_lead_time()
     and v_scheduled_at < pg_catalog.clock_timestamp() + interval '4 hours' then
    raise exception 'New bookings require at least four hours before the session.'
      using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_booking_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event text;
  v_snapshot jsonb;
begin
  if old.status = 'pending' and new.status = 'confirmed' and new.ticket_deducted is true then
    v_event := 'booking_confirmed';
  elsif old.status = 'confirmed' and new.status = 'cancelled'
    and new.end_reason in ('user_cancelled_early', 'user_cancelled_late') then
    v_event := 'booking_cancelled';
  else
    return new;
  end if;
  if new.learner_id is null or new.partner_user_id is null or new.scheduled_at is null then
    raise exception 'Incomplete booking notification identity';
  end if;
  v_snapshot := pg_catalog.jsonb_build_object(
    'learner_id', new.learner_id, 'partner_user_id', new.partner_user_id,
    'scheduled_at', new.scheduled_at, 'language', new.language,
    'end_reason', new.end_reason, 'ticket_refunded', new.ticket_refunded,
    'partner_rewarded', new.partner_rewarded
  );
  insert into public.booking_notification_log(event_key, booking_id, event_type, recipient_role, recipient_user_id, snapshot)
  values (v_event || ':' || new.id::text || ':partner', new.id, v_event, 'partner', new.partner_user_id, v_snapshot)
  on conflict (booking_id, event_type, recipient_role) do nothing;
  if v_event = 'booking_confirmed' then
    insert into public.booking_notification_log(event_key, booking_id, event_type, recipient_role, recipient_user_id, snapshot)
    values (v_event || ':' || new.id::text || ':learner', new.id, v_event, 'learner', new.learner_id, v_snapshot)
    on conflict (booking_id, event_type, recipient_role) do nothing;
  end if;
  return new;
exception when others then
  -- Notification enqueue failures must not roll back booking/ticket/cancellation.
  -- Monitor this code in database logs; no email or token is included.
  raise warning 'DAYO_BOOKING_NOTIFICATION_ENQUEUE_FAILED SQLSTATE=%', sqlstate;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_partner_booking_brief(p_booking_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_learner_id uuid;
  v_language text;
  v_brief jsonb;
  v_nickname text;
  v_email text;
begin
  if auth.uid() is null or p_booking_id is null then
    return null;
  end if;

  select b.learner_id, b.language, b.conversation_brief
    into v_learner_id, v_language, v_brief
  from public.bookings b
  where b.id = p_booking_id
    and b.partner_user_id = auth.uid()
    and b.status = 'confirmed';

  if not found then
    return null;
  end if;

  select p.nickname, p.email
    into v_nickname, v_email
  from public.profiles p
  where p.id = v_learner_id or p.user_id = v_learner_id
  order by case when p.id = v_learner_id then 0 else 1 end
  limit 1;

  v_nickname := nullif(pg_catalog.btrim(v_nickname), '');
  if v_nickname is null
     or pg_catalog.strpos(v_nickname, '@') > 0
     or v_nickname ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     or (v_email is not null
         and pg_catalog.lower(v_nickname) = pg_catalog.split_part(pg_catalog.lower(v_email), '@', 1)) then
    v_nickname := 'DayO User';
  end if;

  return pg_catalog.jsonb_build_object(
    'learner_display_name', v_nickname,
    'language', v_language,
    'conversation_brief', v_brief
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_profiles_role_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_rpc_owner name;
begin
  if tg_op = 'INSERT' then
    -- Defaults and the Auth signup trigger insert 'user'. A browser must
    -- not create a privileged profile via the existing broad INSERT policy.
    if new.role is distinct from 'user' then
      raise exception 'Profile role must start as user.' using errcode = '42501';
    end if;
    return new;
  end if;

  -- Without this narrow guard, broad UPDATE policies could let a client
  -- rebind an existing admin row to its own auth.uid() without editing role.
  if old.role = 'admin' and (
    new.id is distinct from old.id or
    new.user_id is distinct from old.user_id or
    new.client_key is distinct from old.client_key
  ) then
    raise exception 'Admin profile identity cannot be changed here.'
      using errcode = '42501';
  end if;

  if new.role is distinct from old.role then
    select pg_catalog.pg_get_userbyid(proowner) into v_rpc_owner
    from pg_catalog.pg_proc
    where oid = 'public.admin_set_user_role(uuid,text)'::pg_catalog.regprocedure;

    if v_rpc_owner is null
       or current_user <> v_rpc_owner
       or pg_catalog.current_setting('dayo.admin_role_rpc', true) is distinct from 'on' then
      raise exception 'Profile role can only be changed by the admin RPC.'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.refresh_ticket_balance_cache(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_balance bigint;
begin
  if p_user_id is null then
    raise exception 'A user is required.' using errcode = '22023';
  end if;

  perform 1 from public.profiles where id = p_user_id for update;
  if not found then
    raise exception 'Profile not found.' using errcode = 'P0002';
  end if;

  select coalesce(pg_catalog.sum(l.quantity_remaining), 0)
    into v_balance
    from public.ticket_lots l
   where l.user_id = p_user_id
     and l.quantity_remaining > 0
     and (l.expires_at is null or l.expires_at > pg_catalog.now());

  if v_balance > 2147483647 then
    raise exception 'Ticket balance exceeds integer range.' using errcode = '22003';
  end if;

  update public.profiles
     set ticket_count = v_balance::integer,
         updated_at = pg_catalog.now()
   where id = p_user_id;

  return v_balance::integer;
end;
$function$

CREATE OR REPLACE FUNCTION public.refund_booking_ticket(p_booking_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_learner_id uuid;
  v_partner_id uuid;
  v_deducted boolean;
  v_refunded boolean;
  v_allocation public.ticket_allocations%rowtype;
  v_lot public.ticket_lots%rowtype;
  v_has_allocation boolean;
  v_ticket_count integer;
begin
  if v_actor_id is null or p_booking_id is null or p_reason is null
     or p_reason not in ('tech_issue', 'safety_report') then
    raise exception 'Invalid booking refund request.' using errcode = '42501';
  end if;

  select learner_id, partner_user_id, ticket_deducted, ticket_refunded
    into v_learner_id, v_partner_id, v_deducted, v_refunded
    from public.bookings
   where id = p_booking_id
   for update;

  if not found
     or (v_actor_id is distinct from v_learner_id
         and v_actor_id is distinct from v_partner_id) then
    raise exception 'Booking participant access is required.' using errcode = '42501';
  end if;

  select * into v_allocation
    from public.ticket_allocations
   where booking_id = p_booking_id
   for update;
  v_has_allocation := found;

  if not v_has_allocation then
    if coalesce(v_refunded, false) and not coalesce(v_deducted, false) then
      raise exception 'Booking refund state has no ticket deduction.' using errcode = '23514';
    end if;

    if coalesce(v_deducted, false) then
      if not exists (
        select 1 from public.ticket_consumption_pre_cutover_bookings
         where booking_id = p_booking_id
      ) then
        raise exception 'Deducted booking has no ticket allocation.' using errcode = '23514';
      end if;

      select ticket_count into v_ticket_count
        from public.profiles where id = v_learner_id;

      -- 054 discarded every fake legacy entitlement. Historical bookings
      -- cannot restore a lot that never had an allocation. Keep the session
      -- incident report, but require explicit admin review for compensation.
      return pg_catalog.jsonb_build_object(
        'refunded', coalesce(v_refunded, false),
        'already_refunded', coalesce(v_refunded, false),
        'refund_unavailable', not coalesce(v_refunded, false),
        'refund_code', 'historical_no_allocation',
        'ticket_count', v_ticket_count
      );
    end if;

    select ticket_count into v_ticket_count
      from public.profiles where id = v_learner_id;
    return pg_catalog.jsonb_build_object(
      'refunded', false, 'already_refunded', false,
      'refund_unavailable', false, 'ticket_count', v_ticket_count
    );
  end if;

  if not coalesce(v_deducted, false) then
    raise exception 'Ticket allocation exists without booking deduction.' using errcode = '23514';
  end if;

  -- 055 grants and 056 consumption lock profile before lot. Match that order
  -- after booking/allocation to prevent a grant/refund deadlock.
  perform 1 from public.profiles where id = v_learner_id for update;
  if not found then
    raise exception 'Learner profile not found.' using errcode = 'P0002';
  end if;

  select * into v_lot
    from public.ticket_lots
   where id = v_allocation.ticket_lot_id
   for update;
  if not found or v_lot.user_id is distinct from v_learner_id
     or v_allocation.quantity is distinct from 1 then
    raise exception 'Ticket allocation does not belong to the learner lot.' using errcode = '23514';
  end if;

  if coalesce(v_refunded, false) is distinct from (v_allocation.refunded_at is not null) then
    raise exception 'Booking and allocation refund state disagree.' using errcode = '23514';
  end if;

  if v_allocation.refunded_at is not null then
    select ticket_count into v_ticket_count
      from public.profiles where id = v_learner_id;
    return pg_catalog.jsonb_build_object(
      'refunded', true, 'already_refunded', true,
      'refund_unavailable', false, 'ticket_count', v_ticket_count
    );
  end if;

  if v_lot.quantity_remaining >= v_lot.quantity_issued then
    raise exception 'Original ticket lot has no room for a refund.' using errcode = '23514';
  end if;

  update public.ticket_lots
     set quantity_remaining = quantity_remaining + 1,
         updated_at = pg_catalog.now()
   where id = v_lot.id
     and quantity_remaining < quantity_issued;
  if not found then
    raise exception 'Ticket lot changed while refunding.' using errcode = '40001';
  end if;

  update public.ticket_allocations
     set refunded_at = pg_catalog.now(),
         refund_reason = p_reason
   where id = v_allocation.id
     and booking_id = p_booking_id
     and refunded_at is null;
  if not found then
    raise exception 'Ticket allocation changed while refunding.' using errcode = '40001';
  end if;

  update public.bookings
     set ticket_refunded = true,
         updated_at = pg_catalog.now()
   where id = p_booking_id
     and ticket_refunded = false;
  if not found then
    raise exception 'Booking refund state changed.' using errcode = '40001';
  end if;

  -- The helper excludes expired lots, so an expired restore remains in audit
  -- history without granting a new usable ticket or extending its expiry.
  v_ticket_count := public.refresh_ticket_balance_cache(v_learner_id);

  return pg_catalog.jsonb_build_object(
    'refunded', true, 'already_refunded', false,
    'refund_unavailable', false, 'ticket_count', v_ticket_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.save_partner_profile_completion(p_details jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_location text; v_visa text; v_korean text; v_capacity text;
  v_native text[]; v_session text[]; v_availability text[];
  v_other jsonb; v_entry jsonb; v_language text; v_level text;
  v_seen text[] := '{}'::text[];
  v_result public.partner_profile_details;
begin
  if v_uid is null then raise exception 'Partner access required.' using errcode = '42501'; end if;
  perform 1 from public.profiles where id = v_uid and role = 'partner' for share;
  if not found then raise exception 'Partner access required.' using errcode = '42501'; end if;
  if p_details is null or jsonb_typeof(p_details) is distinct from 'object'
    or p_details -> 'guide_acknowledged' is distinct from 'true'::jsonb then
    raise exception 'Read and acknowledge the DayO Partner Guide.' using errcode = '22023';
  end if;
  v_location := p_details ->> 'location_status'; v_visa := p_details ->> 'visa_type';
  v_korean := p_details ->> 'korean_level'; v_capacity := p_details ->> 'weekly_session_capacity';
  if v_location is null or v_location not in ('korea','overseas')
    or v_visa is null or (v_location = 'korea' and v_visa not in ('D-2','D-4','F-series','Other visa'))
    or (v_location = 'overseas' and v_visa <> 'not_applicable_overseas')
    or v_korean is null or v_korean not in ('none','basic','conversational','advanced','native')
    or v_capacity is null or v_capacity not in ('1-2','3-5','6-10','10+') then
    raise exception 'Complete location, visa, Korean level and weekly capacity.' using errcode = '22023';
  end if;
  if jsonb_typeof(p_details -> 'native_languages') is distinct from 'array'
    or jsonb_typeof(p_details -> 'session_languages') is distinct from 'array'
    or jsonb_typeof(p_details -> 'availability_periods') is distinct from 'array'
    or jsonb_typeof(p_details -> 'other_languages') is distinct from 'array' then
    raise exception 'Invalid language or availability selections.' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(p_details -> 'native_languages') x where jsonb_typeof(x) <> 'string')
    or exists (select 1 from jsonb_array_elements(p_details -> 'session_languages') x where jsonb_typeof(x) <> 'string')
    or exists (select 1 from jsonb_array_elements(p_details -> 'availability_periods') x where jsonb_typeof(x) <> 'string') then
    raise exception 'Selections must be text.' using errcode = '22023';
  end if;
  select array_agg(btrim(value)) into v_native from jsonb_array_elements_text(p_details -> 'native_languages');
  select array_agg(btrim(value)) into v_session from jsonb_array_elements_text(p_details -> 'session_languages');
  select array_agg(value) into v_availability from jsonb_array_elements_text(p_details -> 'availability_periods');
  if coalesce(cardinality(v_native),0) not between 1 and 14
    or coalesce(cardinality(v_session),0) not between 1 and 28
    or coalesce(cardinality(v_availability),0) not between 1 and 10
    or exists (select 1 from unnest(v_native || v_session) l where l is null or length(l) not between 1 and 100)
    or cardinality(v_native) <> (select count(distinct lower(l)) from unnest(v_native) l)
    or cardinality(v_session) <> (select count(distinct lower(l)) from unnest(v_session) l)
    or cardinality(v_availability) <> (select count(distinct l) from unnest(v_availability) l)
    or not (v_availability <@ array['weekday_early_morning','weekday_morning','weekday_afternoon','weekday_evening','weekday_late_night',
      'weekend_early_morning','weekend_morning','weekend_afternoon','weekend_evening','weekend_late_night']::text[]) then
    raise exception 'Choose valid, distinct languages and KST availability.' using errcode = '22023';
  end if;
  v_other := p_details -> 'other_languages';
  if jsonb_array_length(v_other) > 14 then raise exception 'Too many other languages.' using errcode = '22023'; end if;
  for v_entry in select value from jsonb_array_elements(v_other) loop
    v_language := btrim(v_entry ->> 'language'); v_level := v_entry ->> 'level';
    if jsonb_typeof(v_entry) <> 'object' or jsonb_typeof(v_entry -> 'language') is distinct from 'string'
      or v_language is null or length(v_language) not between 1 and 100
      or v_level is null or v_level not in ('basic','conversational','fluent','native')
      or lower(v_language) = any(v_seen)
      or exists (select 1 from unnest(v_native) l where lower(l) = lower(v_language)) then
      raise exception 'Invalid other language proficiency.' using errcode = '22023';
    end if;
    v_seen := array_append(v_seen,lower(v_language));
  end loop;
  if exists (select 1 from unnest(v_session) l where not (l = any(v_native)) and not exists (
    select 1 from jsonb_array_elements(v_other) o where btrim(o ->> 'language') = l and o ->> 'level' in ('fluent','native'))) then
    raise exception 'Session languages must be native or fluent.' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('language',btrim(o ->> 'language'),'level',o ->> 'level')),'[]'::jsonb)
    into v_other from jsonb_array_elements(v_other) o;
  insert into public.partner_profile_details(partner_id,location_status,visa_type,native_languages,other_languages,
    session_languages,korean_level,availability_periods,weekly_session_capacity,partner_guide_acknowledged_at,completed_at)
  values(v_uid,v_location,v_visa,v_native,v_other,v_session,v_korean,v_availability,v_capacity,now(),now())
  on conflict (partner_id) do update set location_status = excluded.location_status, visa_type = excluded.visa_type,
    native_languages = excluded.native_languages, other_languages = excluded.other_languages,
    session_languages = excluded.session_languages, korean_level = excluded.korean_level,
    availability_periods = excluded.availability_periods, weekly_session_capacity = excluded.weekly_session_capacity,
    partner_guide_acknowledged_at = coalesce(partner_profile_details.partner_guide_acknowledged_at,excluded.partner_guide_acknowledged_at),
    completed_at = coalesce(partner_profile_details.completed_at,excluded.completed_at), updated_at = now()
  returning * into v_result;
  return to_jsonb(v_result);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_partner_capabilities(p_partner_id uuid, p_conversation_languages text[], p_korean_support_level text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_languages text[];
begin
  if v_actor_id is null or not public.dayo_is_admin() then
    raise exception 'Admin access is required.' using errcode = '42501';
  end if;
  if p_partner_id is null then
    raise exception 'A partner is required.' using errcode = '22023';
  end if;
  if p_conversation_languages is null
     or pg_catalog.cardinality(p_conversation_languages) = 0
     or pg_catalog.cardinality(p_conversation_languages) > 4
     or pg_catalog.array_position(p_conversation_languages, null) is not null
     or not (p_conversation_languages <@ array['en', 'es', 'fr', 'ko']::text[]) then
    raise exception 'Invalid conversation languages.' using errcode = '22023';
  end if;
  if p_korean_support_level is not null
     and p_korean_support_level not in ('none', 'basic', 'conversational', 'fluent') then
    raise exception 'Invalid Korean support level.' using errcode = '22023';
  end if;
  if (select pg_catalog.count(*) from pg_catalog.unnest(p_conversation_languages) as u(language_code))
     <> (select pg_catalog.count(distinct u.language_code)
           from pg_catalog.unnest(p_conversation_languages) as u(language_code)) then
    raise exception 'Duplicate conversation language.' using errcode = '22023';
  end if;

  perform 1 from public.profiles where id = p_partner_id and role = 'partner' for update;
  if not found then
    raise exception 'Partner profile not found.' using errcode = 'P0002';
  end if;

  v_languages := p_conversation_languages;
  insert into public.partner_capabilities (
    partner_id, conversation_languages, korean_support_level, updated_by
  ) values (
    p_partner_id, v_languages, p_korean_support_level, v_actor_id
  )
  on conflict (partner_id) do update
    set conversation_languages = excluded.conversation_languages,
        korean_support_level = excluded.korean_support_level,
        updated_at = pg_catalog.now(),
        updated_by = excluded.updated_by;

  return pg_catalog.jsonb_build_object(
    'success', true,
    'conversation_languages', v_languages,
    'korean_support_level', p_korean_support_level,
    'configured', p_korean_support_level is not null
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.checkout_private_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
